     1→// ============================================================================
     2→// FreeLang Schema 모듈 - SoA 기반 테이블 스키마
     3→// ============================================================================
     4→// 목표: SQL-like 쿼리 엔진의 기반이 되는 테이블 스키마 및 행 저장 구조
     5→// 원리:
     6→//   1. SoA(Structure of Arrays): int_cols[col_idx * MAX_ROWS + row_idx]
     7→//   2. 소프트 삭제: deleted_flags로 논리 삭제 (트랜잭션 롤백용)
     8→//   3. 타입 분리: int_cols / str_cols / bool_cols 별도 배열
     9→// 구조:
    10→//   - 상수 정의 (타입, 에러 코드, 제한값)
    11→//   - ColumnDef, TableSchema, RecordRow, Table 구조체
    12→//   - 스키마 관리 함수
    13→//   - 테이블 CRUD 함수
    14→// ============================================================================
    15→
    16→module schema {
    17→    // === 컬럼 타입 ===
    18→    const COL_TYPE_INT:   i32 = 1;
    19→    const COL_TYPE_STR:   i32 = 2;
    20→    const COL_TYPE_BOOL:  i32 = 3;
    21→
    22→    // === 제한값 ===
    23→    const MAX_COLS:  i32 = 16;
    24→    const MAX_ROWS:  i32 = 1024;
    25→
    26→    // === 에러 코드 ===
    27→    const SCHEMA_OK:          i32 = 0;
    28→    const SCHEMA_ERR_FULL:    i32 = 1;
    29→    const SCHEMA_ERR_TYPE:    i32 = 2;
    30→    const SCHEMA_ERR_DELETED: i32 = 3;
    31→    const SCHEMA_ERR_NOTFOUND: i32 = 4;
    32→
    33→    // === 데이터 구조체 ===
    34→
    35→    // 컬럼 정의
    36→    struct ColumnDef {
    37→        name:     string;
    38→        col_type: i32;
    39→        nullable: bool;
    40→    }
    41→
    42→    // 테이블 스키마 (DDL)
    43→    struct TableSchema {
    44→        name:        string;
    45→        col_defs:    [ColumnDef];
    46→        col_count:   i32;
    47→        primary_key: i32;    // 기본키 컬럼 인덱스 (0 = 첫 번째)
    48→    }
    49→
    50→    // 행 레코드 (SELECT 결과)
    51→    struct RecordRow {
    52→        row_id:     i64;
    53→        int_vals:   [i64];
    54→        str_vals:   [string];
    55→        bool_vals:  [bool];
    56→        is_deleted: bool;
    57→    }
    58→
    59→    // 테이블 (SoA 레이아웃)
    60→    struct Table {
    61→        schema:        TableSchema;
    62→        // 플래튼 SoA 배열: [col_idx * MAX_ROWS + row_idx]
    63→        int_cols:      [i64];
    64→        str_cols:      [string];
    65→        bool_cols:     [bool];
    66→        // 메타데이터
    67→        deleted_flags: [bool];
    68→        row_ids:       [i64];
    69→        row_count:     i32;
    70→        next_id:       i64;
    71→    }
    72→
    73→    // === 스키마 함수 ===
    74→
    75→    // 스키마 생성
    76→    func schema_new(name: string) -> TableSchema {
    77→        return TableSchema{
    78→            name:        name,
    79→            col_defs:    make([ColumnDef], MAX_COLS),
    80→            col_count:   0,
    81→            primary_key: 0,
    82→        };
    83→    }
    84→
    85→    // 컬럼 추가
    86→    func (s: *TableSchema) schema_add_col(name: string, col_type: i32, nullable: bool) -> bool {
    87→        if s.col_count >= MAX_COLS {
    88→            return false;
    89→        }
    90→        s.col_defs[s.col_count] = ColumnDef{
    91→            name:     name,
    92→            col_type: col_type,
    93→            nullable: nullable,
    94→        };
    95→        s.col_count = s.col_count + 1;
    96→        return true;
    97→    }
    98→
    99→    // 컬럼 이름으로 인덱스 찾기
   100→    func (s: *TableSchema) schema_find_col(name: string) -> (i32, bool) {
   101→        let i = 0;
   102→        for i = 0; i < s.col_count; i = i + 1 {
   103→            if s.col_defs[i].name == name {
   104→                return (i, true);
   105→            }
   106→        }
   107→        return (-1, false);
   108→    }
   109→
   110→    // 특정 타입 컬럼의 타입 내부 인덱스 계산
   111→    // (int_cols 배열 내에서 col_idx번째 INT 컬럼의 순서)
   112→    @inline
   113→    func (s: *TableSchema) col_type_idx(col_idx: i32) -> i32 {
   114→        let count = 0;
   115→        let target_type = s.col_defs[col_idx].col_type;
   116→        let i = 0;
   117→        for i = 0; i < col_idx; i = i + 1 {
   118→            if s.col_defs[i].col_type == target_type {
   119→                count = count + 1;
   120→            }
   121→        }
   122→        return count;
   123→    }
   124→
   125→    // 타입별 컬럼 수 계산
   126→    @inline
   127→    func (s: *TableSchema) count_cols_of_type(col_type: i32) -> i32 {
   128→        let count = 0;
   129→        let i = 0;
   130→        for i = 0; i < s.col_count; i = i + 1 {
   131→            if s.col_defs[i].col_type == col_type {
   132→                count = count + 1;
   133→            }
   134→        }
   135→        return count;
   136→    }
   137→
   138→    // === 테이블 함수 ===
   139→
   140→    // 테이블 생성 (SoA 배열 초기화)
   141→    func table_new(s: TableSchema) -> Table {
   142→        return Table{
   143→            schema:        s,
   144→            int_cols:      make([i64],    MAX_COLS * MAX_ROWS),
   145→            str_cols:      make([string], MAX_COLS * MAX_ROWS),
   146→            bool_cols:     make([bool],   MAX_COLS * MAX_ROWS),
   147→            deleted_flags: make([bool],   MAX_ROWS),
   148→            row_ids:       make([i64],    MAX_ROWS),
   149→            row_count:     0,
   150→            next_id:       1,
   151→        };
   152→    }
   153→
   154→    // 행 삽입 (row_id 반환)
   155→    func (t: *Table) table_insert(row: RecordRow) -> (i64, bool) {
   156→        if t.row_count >= MAX_ROWS {
   157→            return (0, false);
   158→        }
   159→
   160→        let row_idx = t.row_count;
   161→        let row_id = t.next_id;
   162→
   163→        // row_id 및 삭제 플래그 기록
   164→        t.row_ids[row_idx] = row_id;
   165→        t.deleted_flags[row_idx] = false;
   166→
   167→        // INT 컬럼 저장
   168→        let int_type_idx = 0;
   169→        let i = 0;
   170→        for i = 0; i < t.schema.col_count; i = i + 1 {
   171→            if t.schema.col_defs[i].col_type == COL_TYPE_INT {
   172→                let flat_idx = i * MAX_ROWS + row_idx;
   173→                if int_type_idx < MAX_COLS {
   174→                    t.int_cols[flat_idx] = row.int_vals[int_type_idx];
   175→                }
   176→                int_type_idx = int_type_idx + 1;
   177→            }
   178→        }
   179→
   180→        // STR 컬럼 저장
   181→        let str_type_idx = 0;
   182→        for i = 0; i < t.schema.col_count; i = i + 1 {
   183→            if t.schema.col_defs[i].col_type == COL_TYPE_STR {
   184→                let flat_idx = i * MAX_ROWS + row_idx;
   185→                if str_type_idx < MAX_COLS {
   186→                    t.str_cols[flat_idx] = row.str_vals[str_type_idx];
   187→                }
   188→                str_type_idx = str_type_idx + 1;
   189→            }
   190→        }
   191→
   192→        // BOOL 컬럼 저장
   193→        let bool_type_idx = 0;
   194→        for i = 0; i < t.schema.col_count; i = i + 1 {
   195→            if t.schema.col_defs[i].col_type == COL_TYPE_BOOL {
   196→                let flat_idx = i * MAX_ROWS + row_idx;
   197→                if bool_type_idx < MAX_COLS {
   198→                    t.bool_cols[flat_idx] = row.bool_vals[bool_type_idx];
   199→                }
   200→                bool_type_idx = bool_type_idx + 1;
   201→            }
   202→        }
   203→
   204→        t.row_count = t.row_count + 1;
   205→        t.next_id = t.next_id + 1;
   206→        return (row_id, true);
   207→    }
   208→
   209→    // row_id → row_idx 변환 (선형 탐색)
   210→    @inline
   211→    func (t: *Table) find_row_idx(row_id: i64) -> (i32, bool) {
   212→        let i = 0;
   213→        for i = 0; i < t.row_count; i = i + 1 {
   214→            if t.row_ids[i] == row_id && !t.deleted_flags[i] {
   215→                return (i, true);
   216→            }
   217→        }
   218→        return (-1, false);
   219→    }
   220→
   221→    // row_idx → RecordRow 변환
   222→    func (t: *Table) row_to_record(row_idx: i32) -> RecordRow {
   223→        let row = RecordRow{
   224→            row_id:     t.row_ids[row_idx],
   225→            int_vals:   make([i64],    MAX_COLS),
   226→            str_vals:   make([string], MAX_COLS),
   227→            bool_vals:  make([bool],   MAX_COLS),
   228→            is_deleted: t.deleted_flags[row_idx],
   229→        };
   230→
   231→        // INT 컬럼 추출
   232→        let int_type_idx = 0;
   233→        let i = 0;
   234→        for i = 0; i < t.schema.col_count; i = i + 1 {
   235→            if t.schema.col_defs[i].col_type == COL_TYPE_INT {
   236→                row.int_vals[int_type_idx] = t.int_cols[i * MAX_ROWS + row_idx];
   237→                int_type_idx = int_type_idx + 1;
   238→            }
   239→        }
   240→
   241→        // STR 컬럼 추출
   242→        let str_type_idx = 0;
   243→        for i = 0; i < t.schema.col_count; i = i + 1 {
   244→            if t.schema.col_defs[i].col_type == COL_TYPE_STR {
   245→                row.str_vals[str_type_idx] = t.str_cols[i * MAX_ROWS + row_idx];
   246→                str_type_idx = str_type_idx + 1;
   247→            }
   248→        }
   249→
   250→        // BOOL 컬럼 추출
   251→        let bool_type_idx = 0;
   252→        for i = 0; i < t.schema.col_count; i = i + 1 {
   253→            if t.schema.col_defs[i].col_type == COL_TYPE_BOOL {
   254→                row.bool_vals[bool_type_idx] = t.bool_cols[i * MAX_ROWS + row_idx];
   255→                bool_type_idx = bool_type_idx + 1;
   256→            }
   257→        }
   258→
   259→        return row;
   260→    }
   261→
   262→    // ID로 행 조회
   263→    func (t: *Table) table_get(row_id: i64) -> (RecordRow, bool) {
   264→        let row_idx, found = t.find_row_idx(row_id);
   265→        if !found {
   266→            return (RecordRow{
   267→                row_id:     0,
   268→                int_vals:   make([i64], MAX_COLS),
   269→                str_vals:   make([string], MAX_COLS),
   270→                bool_vals:  make([bool], MAX_COLS),
   271→                is_deleted: true,
   272→            }, false);
   273→        }
   274→        return (t.row_to_record(row_idx), true);
   275→    }
   276→
   277→    // INT 컬럼 업데이트
   278→    func (t: *Table) table_update_int(row_id: i64, col_idx: i32, val: i64) -> bool {
   279→        if col_idx < 0 || col_idx >= t.schema.col_count {
   280→            return false;
   281→        }
   282→        if t.schema.col_defs[col_idx].col_type != COL_TYPE_INT {
   283→            return false;
   284→        }
   285→        let row_idx, found = t.find_row_idx(row_id);
   286→        if !found {
   287→            return false;
   288→        }
   289→        t.int_cols[col_idx * MAX_ROWS + row_idx] = val;
   290→        return true;
   291→    }
   292→
   293→    // STR 컬럼 업데이트
   294→    func (t: *Table) table_update_str(row_id: i64, col_idx: i32, val: string) -> bool {
   295→        if col_idx < 0 || col_idx >= t.schema.col_count {
   296→            return false;
   297→        }
   298→        if t.schema.col_defs[col_idx].col_type != COL_TYPE_STR {
   299→            return false;
   300→        }
   301→        let row_idx, found = t.find_row_idx(row_id);
   302→        if !found {
   303→            return false;
   304→        }
   305→        t.str_cols[col_idx * MAX_ROWS + row_idx] = val;
   306→        return true;
   307→    }
   308→
   309→    // BOOL 컬럼 업데이트
   310→    func (t: *Table) table_update_bool(row_id: i64, col_idx: i32, val: bool) -> bool {
   311→        if col_idx < 0 || col_idx >= t.schema.col_count {
   312→            return false;
   313→        }
   314→        if t.schema.col_defs[col_idx].col_type != COL_TYPE_BOOL {
   315→            return false;
   316→        }
   317→        let row_idx, found = t.find_row_idx(row_id);
   318→        if !found {
   319→            return false;
   320→        }
   321→        t.bool_cols[col_idx * MAX_ROWS + row_idx] = val;
   322→        return true;
   323→    }
   324→
   325→    // 소프트 삭제
   326→    func (t: *Table) table_delete(row_id: i64) -> bool {
   327→        let row_idx, found = t.find_row_idx(row_id);
   328→        if !found {
   329→            return false;
   330→        }
   331→        t.deleted_flags[row_idx] = true;
   332→        return true;
   333→    }
   334→
   335→    // 살아있는 행 수
   336→    func (t: *Table) table_count() -> i32 {
   337→        let count = 0;
   338→        let i = 0;
   339→        for i = 0; i < t.row_count; i = i + 1 {
   340→            if !t.deleted_flags[i] {
   341→                count = count + 1;
   342→            }
   343→        }
   344→        return count;
   345→    }
   346→
   347→    // 인덱스로 행 조회 (query.fl 내부 사용)
   348→    func (t: *Table) table_get_row(row_idx: i32) -> RecordRow {
   349→        return t.row_to_record(row_idx);
   350→    }
   351→
   352→    // 행이 살아있는지 확인
   353→    @inline
   354→    func (t: *Table) is_alive(row_idx: i32) -> bool {
   355→        return row_idx >= 0 && row_idx < t.row_count && !t.deleted_flags[row_idx];
   356→    }
   357→
   358→    // INT 컬럼 값 직접 접근 (query.fl 최적화용)
   359→    @inline
   360→    func (t: *Table) get_int_val(row_idx: i32, col_idx: i32) -> i64 {
   361→        return t.int_cols[col_idx * MAX_ROWS + row_idx];
   362→    }
   363→
   364→    // STR 컬럼 값 직접 접근
   365→    @inline
   366→    func (t: *Table) get_str_val(row_idx: i32, col_idx: i32) -> string {
   367→        return t.str_cols[col_idx * MAX_ROWS + row_idx];
   368→    }
   369→
   370→    // BOOL 컬럼 값 직접 접근
   371→    @inline
   372→    func (t: *Table) get_bool_val(row_idx: i32, col_idx: i32) -> bool {
   373→        return t.bool_cols[col_idx * MAX_ROWS + row_idx];
   374→    }
   375→
   376→    // RecordRow 생성 헬퍼
   377→    func record_new() -> RecordRow {
   378→        return RecordRow{
   379→            row_id:     0,
   380→            int_vals:   make([i64],    MAX_COLS),
   381→            str_vals:   make([string], MAX_COLS),
   382→            bool_vals:  make([bool],   MAX_COLS),
   383→            is_deleted: false,
   384→        };
   385→    }
   386→
   387→    // === 통계 함수 ===
   388→
   389→    func (t: *Table) table_stats() -> string {
   390→        let alive = t.table_count();
   391→        let msg = "[Table " + t.schema.name + "] rows=" + i32_to_str(t.row_count) +
   392→                  " alive=" + i32_to_str(alive) +
   393→                  " deleted=" + i32_to_str(t.row_count - alive) +
   394→                  " cols=" + i32_to_str(t.schema.col_count) +
   395→                  " next_id=" + i64_to_str(t.next_id);
   396→        return msg;
   397→    }
   398→
   399→    // === 헬퍼 함수 ===
   400→
   401→    @inline
   402→    func i32_to_str(n: i32) -> string {
   403→        if n == 0 { return "0"; }
   404→        if n == 1 { return "1"; }
   405→        if n == 2 { return "2"; }
   406→        if n == 3 { return "3"; }
   407→        if n == 4 { return "4"; }
   408→        if n == 5 { return "5"; }
   409→        if n == 6 { return "6"; }
   410→        if n == 7 { return "7"; }
   411→        if n == 8 { return "8"; }
   412→        if n == 9 { return "9"; }
   413→        if n < 0 { return "-" + i32_to_str(-n); }
   414→        let d = n / 10;
   415→        let r = n % 10;
   416→        return i32_to_str(d) + i32_to_str(r);
   417→    }
   418→
   419→    @inline
   420→    func i64_to_str(n: i64) -> string {
   421→        if n == 0 { return "0"; }
   422→        if n < 0 { return "-" + i64_to_str(-n); }
   423→        return i32_to_str(i32(n));
   424→    }
